    $scope.PreGetTreatMentPlan = function (item, index) {
        console.log(item);
        console.log("Pitem");

        if (index !== $scope.TreatmentPlanIndex) {
            $scope.SelectedAppointment = angular.copy(item) || null;
            $scope.TreatmentPlanIndex = index;
            $scope.selectedTreatmentplan = item;
            $scope.DoctorSpecializationId = $scope.selectedTreatmentplan.DoctorSpecializationId;

            if ($scope.DoctorSpecializationId !== 2) {
                if (item.AppointmentTypeId === 8) {//surgery case history        
                    if (angular.equals(item.SelectedSurgery, {})) {
                        $scope.GetSurgerieAppointment(item.AppointmentId, appointmentinfo.PatientID).then(function (resp) {


                            if (resp.data.Status === "Success") {

                                resp.data.rows = resp.data.rows || [];

                                if (resp.data.rows.length > 0) {
                                    resp.data.rows[0].SurgeryDetails = $filter("filter")(resp.data.rows[0].SurgeryDetails, { "AppointmentId": item.AppointmentId }, true);
                                    $scope.SelectedSurgery = angular.copy(resp.data.rows[0]);
                                    if (!angular.equals($scope.SelectedSurgery, {})) {
                                        item.SelectedSurgery = $scope.SelectedSurgery;
                                        item.SurgeryStatusInd = $scope.SelectedSurgery.SurgeryDetails[0].SurgeryStatusInd;
                                        $scope.SelectedSurgery.AllDoctorsList = $scope.Main.clinicDoctorList;
                                        $scope.SelectedSurgery.AppointmentId = item.AppointmentId;
                                        $scope.SelectedSurgery.SurgeonName = item.DoctorName;
                                        appointmentinfo.DoctorFullName = item.DoctorName;
                                        appointmentinfo.MedRegNo = item.MedRegNo;
                                        datapersistanceFactory.set("SelectedSurgery", $scope.SelectedSurgery);






                                        $timeout(function () {
                                            $scope.$broadcast("CallOtHistoryInit", {
                                                "SurgeryStatusInd": $scope.SelectedSurgery.SurgeryDetails[0].SurgeryStatusInd,
                                                "IsCallPreInit": true
                                            });
                                        }, 200);



                                        $scope.Main.SurgeryArray = $scope.SelectedSurgery.SurgeryDetails || [];

                                        $scope.Main.ConsumedIolsArray = $scope.Main.SurgeryArray[0].ConsumedIolsArray || [];

                                        $scope.Main.SurgeonName = $scope.SelectedSurgery.SurgeonName || "";



                                        $scope.Main.SurgeryDoctorId = $scope.SelectedSurgery.SurgeryDetails[0].SurgeryDoctorId;
                                        $scope.Main.SurgerySuggestedDate = item.AppointmentDate;

                                    }
                                }
                            }
                        }, function (err) {
                            console.log(err);
                            alertify.error("Getting surgery data failed");
                        });
                    } else {



                        $timeout(function () {
                            $scope.$broadcast("CallOtHistoryInit", {
                                "SurgeryStatusInd": item.SurgeryStatusInd,
                                "IsCallPreInit": true
                            });
                        }, 200);

                        $scope.Main.SurgeryArray = item.SelectedSurgery.SurgeryDetails || [];

                        $scope.Main.ConsumedIolsArray = $scope.Main.SurgeryArray[0].ConsumedIolsArray || [];

                        $scope.Main.SurgeonName = item.DoctorName || "";

                        $scope.Main.SurgerySuggestedDate = item.AppointmentDate;
                    }
                } else {//Opthalmology case history
                    appointmentinfo.DoctorFullName = item.DoctorName;
                    appointmentinfo.MedRegNo = item.MedRegNo;
                    $scope.GetTreatMentPlan(item, index);
                }
            }
            if ($scope.DoctorSpecializationId === 2) {//dental case history
                appointmentinfo.DoctorFullName = item.DoctorName;
                appointmentinfo.MedRegNo = item.MedRegNo;
                $scope.GetPatientDentalCaseHistorybyId(item, index);
            }
        }

        $scope.caseObj.PatientPastVisitPopUp = false;

    };
