        appInfo.BranchName = branchName;
        appInfo.BranchEmail = branchEmail;
        appInfo.BranchMobile = branchMobile;
        appInfo.DoctorEmail = DoctorEmail;
        appInfo.DoctorName = DoctorName;
        appInfo.BranchId = BranchId;
