    function loadFileData() {
        $scope.generalFileuploadsArray = [];
        $scope.preFileuploadsArray = [];
        $scope.postFileuploadsArray = [];
        $scope.consentFileuploadsArray = [];

        angular.forEach($scope.ForumUploadPDfArray, function (item) {
            switch (item.FileTypeId) {
                case 6:
                    $scope.ForumPdfUploads.push(item);
                    break;

            }

        });
        angular.forEach($scope.ForumUploadImageArray, function (item) {
            switch (item.FileTypeId) {
                case 6:
                    $scope.ForumImgUploads.push(item);
                    break;

            }
        });

        angular.forEach($scope.FileUploadPDfArray, function (item) {
            switch (item.FileTypeId) {
                case 1:
                    $scope.generalPdfUploads.push(item);
                    break;
                case 2:
                    $scope.PreTreatmentPdfUploads.push(item);
                    break;
                case 3:
                    $scope.PostTreatmentPdfUploads.push(item);
                    break;
                case 4:
                    $scope.ConsentPdfUploads.push(item);
                    break;
            }

        });
        angular.forEach($scope.FileUploadImageArray, function (item) {
            switch (item.FileTypeId) {
                case 1:
                    $scope.generalImgUploads.push(item);
                    break;
                case 2:
                    $scope.PreTreatmentImgUploads.push(item);
                    break;
                case 3:
                    $scope.PostTreatmentImgUploads.push(item);
                    break;
                case 4:
                    $scope.ConsentImgUploads.push(item);
                    break;
            }
        });
        $scope.MainfileArray = [];

        if ($scope.generalFileuploadsArray.length > 0) {
            $scope.MainfileArray.push({ headerName: 'General Uploads', list: $scope.generalFileuploadsArray });
        }
        if ($scope.preFileuploadsArray.length > 0) {
            $scope.MainfileArray.push({ headerName: 'Pre-Treatments', list: $scope.preFileuploadsArray });
        }
        if ($scope.postFileuploadsArray.length > 0) {
            $scope.MainfileArray.push({ headerName: 'Post-Treatments', list: $scope.postFileuploadsArray });
        }
        if ($scope.consentFileuploadsArray.length > 0) {
            $scope.MainfileArray.push({ headerName: 'Consents', list: $scope.consentFileuploadsArray });
        }





    }

    $scope.openfileUploads = function (item) {
        if (item.FileExt === 'application/pdf') {
            window.open(item.DocURL);
        } else {
            $scope.FileUploadURlArray = [];
            $scope.FileUploadURlArray.push({
                "url": item.DocURL,
                "thumbUrl": item.DocURL
            });
            Lightbox.openModal($scope.FileUploadURlArray, 0);
        }
    };







