    $scope.ChangeTab = function (tab, past, sideClick) {

        if (tab === 5 || tab === 6) {
            var appoint_info = eHnoteMasterDataService.getAppointmentInfo();
            appoint_info.AppointmentId = appoint_info.AppointmentId || 0;
            if (appoint_info.AppointmentId !== 0) {
                appoint_info.AppointmentStatusId = appoint_info.AppointmentStatusId || null;
                if (appoint_info.AppointmentStatusId == 1 || appoint_info.AppointmentStatusId == null) {
                    var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>The patient isn't Checked In!<br> Do you want to Check In the patient? </h4>", function () {
                        var CurrentTime = $filter("date")(new Date(), "HH:mm:ss");
                        //if (tab === 5) {
                        //    var RoomTypeId = 9;
                        //} else if (tab === 6) {
                        //     var RoomTypeId = 1;
                        //}
                        var params = {
                            "UserId": eHnoteMasterDataService.getLoginId(),
                            "HospitalId": $scope.HospitalId,
                            "AppointmentId": $scope.cacheStorageItem.appointmentid,
                            "AppointmentTrackerDetailId": 0,
                            "RoleId": userLoginDetails.RoleID,
                            "VisitReason": "",
                            "AttenderName": "",
                            "DoctorId": null,
                            "DoctorRoleId": null,
                            "RoomTypeId": 1,
                            "RoomId": null,
                            "CurrentTime": CurrentTime,
                            "IsSendTo": "N",
                            "IsCheckedIn": "Y",
                            "IsCheckedOut": "N",
                            "IsReCheckIn": "N",
                            "IsReCheckOut": "N",
                            "IsExpressCheckedOut": "N",
                            "VisitTypeId": appoint_info.VisitTypeId,
                            "BookingStatusId": appoint_info.BookingStatusId,
                            "HospitalEquipmentId": appoint_info.HospitalEquipmentId || 0

                        }
                        if (params.RoleId == 2) {
                            params.RoomTypeId = 10;
                        }
                        eHnoteMainAppointmentService.AddUpdateAppointmentCheckInTrackerDetails(params).then(function (resp) {
                            if (resp.data.Status == "Success") {
                                alertify.success("Patient CheckIn Successfully");
                                var appoint_info = eHnoteMasterDataService.getAppointmentInfo();
                                appoint_info.AppointmentStatusId = 2;
                                eHnoteMasterDataService.addAppointmentInfo(appoint_info);
                            }
                        }, function (err) {
                            alertify.error("Getting Failed");
                        });

                    }, function () {
                        r = "You pressed Cancel!";
                        $scope.ChangeTab(1, "", true);
                    });
                    //alertify.error("Please make sure patient is checked-in");
                    //return false;
                }


                if (tab === 6) {
                    if (userLoginDetails.RoleID === 1 || userLoginDetails.RoleID === 43 || userLoginDetails.RoleID === 10 || userLoginDetails.RoleID === 16) {

                        if (userLoginDetails.RoleID === 43) {
                            if (appoint_info.DoctorID !== $scope.UserId) {
                                alertify.error("Patient Doesn't Have an Appointment Scheduled for Today!");
                                return false;
                            }
                        }
                    } else {
                        alertify.error("The Charts Can Only Be Accessed by Physicians and Technicians");
                        return false;
                        //if (userLoginDetails.RoleID === 18) {

                        //} else {
                        //    alertify.error("The Charts Can Only Be Accessed by Physicians and Technicians");
                        //    return false;
                        //}

                    }
                    if (userLoginDetails.RoleID === 16 && appoint_info.TrackerDetails[0].RoomTypeId != 1) {
                        alertify.error("Cannot Access Charts, Patient Hasn't Reached the Doctor's Chamber Yet!");
                        return false;
                    }
                }

                /* if (tab === 5) {
                     if (userLoginDetails.RoleID === 2 || userLoginDetails.RoleID === 19 || userLoginDetails.RoleID === 43) {
 
                     } else {
                         alertify.error("Don't Have Access to Billing");
                         return false;
                     }
                 }*/
            } else {
                // alertify.error("Patient Donot Have Appointment Today");
                //alertify.error("Patient Doesn't Have an Appointment Scheduled for Today");
                alertify.error("Patient Does Not Have An Appointment Today");
                return false;
            }
        }


        if (($scope.parentProfileTab.MainTab === 3 || $scope.parentProfileTab.MainTab === 6) && (sideClick == true) && ($scope.ConsultationObj.SummaryView == false) && (tab != 3 && tab != 6)) {
            var r = alertify.confirm(
                "<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre pl-20 pr-20'>Are you sure you want to cancel the consultation , all your unsaved data will be deleted ? </h4>",
                function () {
                    $scope.parentProfileTab.MainTab = tab;
                    ContinueChangeTab(tab, past);

                    if ($scope.IsDynamicCheckInMandatory === true) {
                        if (userLoginDetails.RoleID == 1 || userLoginDetails.RoleID == 10 || userLoginDetails.RoleID == 43) {
                            var params = {
                                "AppointmentId": $scope.cacheStorageItem.appointmentid || 0,
                            };
                            eHnoteMainAppointmentService.GetLatestTrackerStatusById(params).then(function (resp) {
                                if (resp.data.Status === 'Success') {
                                    if (resp.data.rows.length > 0) {
                                        var DynamicStatusarray = resp.data.rows[0];
                                        if ((DynamicStatusarray.RoomTypeId == 1 || DynamicStatusarray.RoomTypeId == 2 || DynamicStatusarray.RoomTypeId == 12) && DynamicStatusarray.Status == 'Active') {
                                            $scope.CurrentTime = $filter("date")(new Date(), "HH:mm:ss");
                                            var params = {
                                                "UserId": eHnoteMasterDataService.getLoginId(),
                                                "TransferUserId": eHnoteMasterDataService.getLoginId(),
                                                "HospitalId": $scope.HospitalId,
                                                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                                                "AppointmentTrackerDetailId": 0,
                                                "RoleId": userLoginDetails.RoleID,
                                                "DoctorId": null,
                                                "DoctorRoleId": null,
                                                "RoomTypeId": null,
                                                "RoomId": null,
                                                "CurrentTime": $scope.CurrentTime,
                                                "VisitTypeId": appoint_info.VisitTypeId,
                                                "BookingStatusId": DynamicStatusarray.BookingStatusId,
                                                "IsSendTo": "N",
                                                "IsRollBack": "Y",
                                                "IsCheckedIn": "N",
                                                "IsCheckedOut": "N",
                                                "IsReCheckIn": "N",
                                                "IsReCheckOut": "N"
                                            }
                                            eHnoteMainAppointmentService.AddUpdateAppointmentTrackerDetails(params).then(function (resp) {
                                            }, function (err) {
                                                console.log(err);
                                                alertify.error("Getting Failed");
                                            });
                                        }
                                    }
                                }
                            }, function (err) {
                                console.log(err);
                                alertify.error("Getting Failed");
                            });
                        }
                    }






                }, function () {
                    return false;
                });
        } else {
            var appoint_info = eHnoteMasterDataService.getAppointmentInfo();
            if ($scope.IsDynamicCheckInMandatory === true && appoint_info.AppointmentStatusId !== 1) {
                if (tab === 6) {
                    var params = {
                        "AppointmentId": $scope.cacheStorageItem.appointmentid || 0,
                    };
                    eHnoteMainAppointmentService.GetLatestTrackerStatusById(params).then(function (resp) {
                        if (resp.data.Status === 'Success') {
                            var DynamicStatusarray = resp.data.rows[0];
                            if (DynamicStatusarray.UserId != $scope.UserId) {
                                if ((userLoginDetails.RoleID == 1 || userLoginDetails.RoleID == 43 || userLoginDetails.RoleID == 10) && (DynamicStatusarray.RoomTypeId == 1 || DynamicStatusarray.RoomTypeId == 2) && DynamicStatusarray.Status == "Active") {
                                    alertify.error("Patient is Active at  " + DynamicStatusarray.UserName + ", So Can't open the Chat");
                                    $scope.parentProfileTab.MainTab = 1;
                                    return false;
                                } else {
                                    ContinueChangeTab(tab, past);
                                }
                            } else {
                                ContinueChangeTab(tab, past);
                            }

                        }
                    }, function (err) {
                        console.log(err);
                        alertify.error("Getting Failed");
                    });


                } else {
                    ContinueChangeTab(tab, past);
                }
            } else {
                ContinueChangeTab(tab, past);
            }


            //ContinueChangeTab(tab, past);
        }

        if (tab === 1) {
            $scope.SelectedAppointmentObj = "";
            $scope.switchTab(1);
        }
        if (tab === 2) {
            $scope.PastVisitsNavObj.Tabchange = 1;
        }
    }
