    $scope.searchReferalDoctors = function (val, typeid) {

        var searchtext = "", searchNPI = "";
        if (isNaN(val)) {
            searchtext = val;
        }
        else {
            searchNPI = val;
        }

        var param = {
            'LocationId': null,
            'PageNumber': 1,
            'PageSize': 20,
            'SearchTaxt': searchtext,
            "SpecializationId": null,
            "DeleteInd": 'N',
            "NPI": searchNPI,
            "RefaralTypeId": typeid,
            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID
        };
        return eHnoteReferalDataService.GetReferalPCPDoctors(param).then(function (resp) {
            if (resp.data.count !== 0) {
                if (resp.data.PcpRefdetails.length > 0) {
                    return resp.data.PcpRefdetails.map(function (item) {
                        return item;
                    });
                }
            }
        }, function (error) {
            console.log(error);
        });
    }

    $scope.changePCPRefereal = function (text) {
        $scope.filteredPCPArray = [];

        if (text === "") {
            $scope.filteredPCPArray = angular.copy($scope.ReferalPCPDoctorsList);
        }
        if (isNaN(text)) {
            $scope.filteredPCPArray = [];
            var patientfilter = $filter("filter")($scope.ReferalPCPDoctorsList, { "DoctorName": text }) || [];
            if (patientfilter.length > 0) {
                $scope.filteredPCPArray = patientfilter;
            }

        } else {
            $scope.filteredPCPArray = [];
            var patientfilter = $filter("filter")($scope.ReferalPCPDoctorsList, { "NPI": text }) || [];
            if (patientfilter.length > 0) {
                $scope.filteredPCPArray = patientfilter;
            }
        }
    };

