    function getMailStr(pval, dval, oval) {
        var strmail = "";
        if (pval)
            strmail = pval;
        if (dval)
            strmail += strmail ? ',' + dval : dval;
        if (oval)
            strmail += strmail ? ',' + oval : oval;
        return strmail;
    }
    $scope.SendEmail = function () {
        var TempPlan = angular.copy($scope.CurrentPlan);
        TempPlan.emailAddresses = getMailStr($scope.eObj.PatientEmail, $scope.eObj.DoctorEmail, $scope.eObj.OtherEmail);
        var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
        TempPlan.PatientName = appointmentinfo.PatientDetails.FullName ? appointmentinfo.PatientDetails.FullName : "";

        appointmentinfo.Title = appointmentinfo.PatientDetails.Title ? appointmentinfo.PatientDetails.Title : "";
        if (appointmentinfo.Title !== "") {
            TempPlan.PatientName = appointmentinfo.Title + "." + TempPlan.PatientName;
        }
        TempPlan.PhoneNumber = appointmentinfo.PatientDetails.MobileNo ? appointmentinfo.PatientDetails.MobileNo : "";

        //if (appointmentinfo.PhoneNumber) {
        //    TempPlan.PhoneNumber = appointmentinfo.PhoneNumber ? appointmentinfo.PhoneNumber : "";
        //} else {
        //    TempPlan.PhoneNumber = appointmentinfo.PatientPhone ? appointmentinfo.PatientPhone[0].PhNumber : "";
        //}
        TempPlan.PatientAddress = "";
        TempPlan.BranchPhone = TempPlan.BranchMobile;
        TempPlan.DoctorName = TempPlan.Appointmentwith;
        TempPlan.PatientAge = "";

        TempPlan.PatientGender = appointmentinfo.Gender;
        appointmentinfo.PatientDetails.AgeInYears = appointmentinfo.PatientDetails.AgeInYears || "";
        if (appointmentinfo.PatientDetails.AgeInYears !== "") {
            TempPlan.PatientAge = appointmentinfo.PatientDetails.AgeInYears + "Y" + " " + appointmentinfo.PatientDetails.AgeInMonths + "M" + " " + appointmentinfo.PatientDetails.AgeInDays + "D";
        } else {
            TempPlan.PatientAge = appointmentinfo.PatientDetails.AgeInMonths + "M" + " " + appointmentinfo.PatientDetails.AgeInDays + "D";
        }

        TempPlan.PatientGst = appointmentinfo.PatientGSTNO;
        TempPlan.PatientId = appointmentinfo.PatientID;
        TempPlan.PatientDisplayId = appointmentinfo.PatientDetails.PatientDisplayId ? appointmentinfo.PatientDetails.PatientDisplayId : "";
        TempPlan.BranchArea = TempPlan.BranchArea || "";
        //TempPlan.OrgGSTNO = "";
        TempPlan.BranchAddress = "";


        //var Branches = $filter("filter")($scope.AllBranches, { "ExtDetails": { "HospitalID": TempPlan.BranchId } }, true);

        //if (Branches.length > 0) {
        if (TempPlan.Address1 !== "" && TempPlan.Address2 !== "") {
            TempPlan.BranchAddress = TempPlan.Address1 + "," + TempPlan.Address2;
        } else if (TempPlan.Address1 !== "" && TempPlan.Address2 === "") {
            TempPlan.BranchAddress = TempPlan.Address1;
        } else if (TempPlan.Address1 === "" && TempPlan.Address2 !== "") {
            TempPlan.BranchAddress = TempPlan.Address2;
        }
        //TempPlan.OrgGSTNO = TempPlan.OrgGSTNO;
        //}

        if ($scope.EmailDataType === "all") {
            TempPlan.UnaidedArray = $scope.UnaidedArray;
            TempPlan.RefractionArray = $scope.RefractionArray;
            TempPlan.AcceptenceArray = $scope.AcceptenceArray;
            TempPlan.KeretometerArray = $scope.KeretometerArray;
            TempPlan.BinocularArray = $scope.BinocularArray;
            TempPlan.OcularDominanceArray = $scope.OcularDominanceArray;
            TempPlan.PinholeArray = $scope.PinholeArray;
            TempPlan.LCVArray = $scope.LCVArray;
            TempPlan.AnteriorSegmentArray = $scope.AnteriorSegmentArray;
            TempPlan.PosteriorSegmentArray = $scope.PosteriorSegmentArray;
            TempPlan.AdditionalInvestgationArray = $scope.AdditionalInvestgationArray;
            TempPlan.GonioscopyArray = $scope.GonioscopyArray;

            if (TempPlan.Vitals !== undefined) {
                var BpHigh = "";
                var BpLow = "";
                for (var i = TempPlan.Vitals.length - 1; i >= 0; i--) {
                    if (TempPlan.Vitals[i].VitalID === 5) {
                        BpLow = TempPlan.Vitals[i].Value;
                    }
                    if (TempPlan.Vitals[i].VitalID === 4) {
                        BpHigh = TempPlan.Vitals[i].Value;
                    }
                    if (TempPlan.Vitals[i].Value === "" || TempPlan.Vitals[i].VitalID === 4 || TempPlan.Vitals[i].VitalID === 5) {
                        TempPlan.Vitals.splice(i, 1);
                    }
                }
                if (BpHigh !== "" && BpLow !== "") {
                    TempPlan.Vitals.push({
                        "VitalID": 18,
                        "VitalDesc": "Bp (mm Hg)",
                        "Value": BpHigh + " / " + BpLow
                    });
                }
            }
            TempPlan.isSendRefLetterMail = $scope.ref.isSendRefLetterMail;
            TempPlan.ConsultDoctorEmail = $scope.eObj.DoctorEmail;
            TempPlan.ReferalDoctorEmail = $scope.eObj.OtherEmail;
            TempPlan.PatientEmail = $scope.eObj.PatientEmail;
            TempPlan.RefDoctorMobile = TempPlan.ReferralDocMobile;
            //TempPlan.PatientMobileNumber = $scope.eObj.PatientEmail;
            TempPlan.specialisation = doctorinfo.specialisation;
            TempPlan.PatientDisplayID = $scope.PatientDisplayID;
            TempPlan.FollowUpDate = $scope.cacheStorageItem.FollowUpDate;
            TempPlan.LabtestList = TempPlan.NewLabTestList;
            TempPlan.IsNewConsultation = TempPlan.ShowNewConsultation;
            TempPlan.ContactLensList = TempPlan.ContactLens || [];
            TempPlan.VisionDetails = TempPlan.VisionDetails || [];
            TempPlan.AnteriorSegmentDetails = TempPlan.AnteriorSegmentDetails || [];
            TempPlan.PosteriorSegmentDetails = TempPlan.PosteriorSegmentDetails || [];
            TempPlan.TonoMetryDetails = TempPlan.TonoMetryDetails || [];
            TempPlan.GlassDetails = TempPlan.GlassDetails || [];
            TempPlan.AnteriorRemarks = TempPlan.AnteriorRemarks || "";
            TempPlan.PosteriorRemarks = TempPlan.PosteriorRemarks || "";
            TempPlan.ColorVisionDetails = TempPlan.ColorVisionDetails || [];
            TempPlan.LacrimalPatiencyDetails = TempPlan.LacrimalPatiencyDetails || [];
            TempPlan.SquintDetails = TempPlan.SquintDetails || [];
            if (TempPlan.GonioscopyDetails.length > 0) {
                angular.forEach(TempPlan.GonioscopyDetails, function (item) {
                    if (item.RightEye.ImagesArray && item.RightEye.ImagesArray.length > 0) {
                        angular.forEach(item.RightEye.ImagesArray, function (initem) {
                            initem.base64Img = "";
                            delete initem.base64Img;
                        });
                    }

                    if (item.LeftEye.ImagesArray && item.LeftEye.ImagesArray.length > 0) {
                        angular.forEach(item.LeftEye.ImagesArray, function (initem) {
                            initem.base64Img = "";
                            delete initem.base64Img;
                        });
                    }
                });

            }
            TempPlan.GonioscopyDetails = TempPlan.GonioscopyDetails || [];

            $scope.PatientInvestigationresult = [];
            if (TempPlan.PatientInvestigations.length !== 0) {
                if ($scope.cacheStorageItem.listofPatientInvestigation.length !== 0) {
                    angular.forEach($scope.cacheStorageItem.listofPatientInvestigation, function (hitem) {
                        var temarray = $filter("filter")(TempPlan.PatientInvestigations, function (item, index) { return item.PatientInvestigationId === hitem.PatientInvestigationId }, true);

                        if (temarray.length !== 0) {
                            $scope.PatientInvestigationresult.push(hitem);
                        }


                    });
                }
            }

            TempPlan.PatientInvestigationresult = $scope.PatientInvestigationresult || [];
            TempPlan.AmslergridDetails = TempPlan.NewAmslerGridArray || [];
            TempPlan.HertelsExaminationDetails = TempPlan.HertelsExaminationArray || [];

            eHnotePatientVisitReasonServices.EmailCaseHistory(TempPlan).then(function (resp) {
                if (resp.data.Status === 2) {
                    alertify.error(resp.data.Message);
                    return;
                }
                if (resp.data.Status === 1) {
                    alertify.success("Mail sent successfully");
                }
            }, function (err) {
                alertify.error("sending email failed");
            });
        } else if ($scope.EmailDataType === "prescription") {
            eHnotePatientVisitReasonServices.EmailCaseHistoryPrescription(TempPlan).then(function (resp) {
                if (resp.data.Message === "Success") {
                    alertify.success("Mail sent successfully");
                }
            }, function (err) {
                alertify.error("sending email failed");
            });
        }
    };
