                        item.Patient.AgeInDays = item.AgeInDays;

                        item.Patient.Gender = item.Gender;
                        item.Patient.LastVisited = item.LastVisited;
                        item.Patient.CountryCode = item.CountryCode;
                        item.Patient.PhoneNumber = item.PhoneNumber;
                        item.Patient.CurrentAge = item.CurrentAge;
