    function GetpatientPaymentObj() {
        var obj = {
            "TotalAvailableDeposit": 0,
            "TotalPatientDue": 0,
            "List": []
        };
        return obj;
    }
    $scope.PatientPaymentObj = GetpatientPaymentObj();
    $scope.getPatientPayment = function (PatientId) {
        PatientId = PatientId || 0;
        if (PatientId == 0) {
            return;
        }
        var params = {
            "PatientId": PatientId
        }
        eHnoteInsuranceService.GetDepositAmountListByPatientID(params).then(function (response) {
            if (response.data.status === "Success") {
                $scope.PatientPaymentObj = GetpatientPaymentObj();
                $scope.PatientPaymentObj.List = response.data.rows || [];
                $scope.PatientPaymentObj.TotalAvailableDeposit = response.data.TotalAvailableDeposit || 0;
                $scope.PatientPaymentObj.TotalPatientDue = response.data.TotalPatientDue || 0;

            } else {
                alertify.error(response.data.Message);
                return false;
            }

        }, function (error) {

        });
    };

    $scope.AddNewPaymentNew = function () {  // 07/12/2022 exist popup used
        $scope.ShowPatientListDrop = false;
        $scope.PatientDepositsPopup = "1";
        var obj = {
            "PatientId": $scope.patientid,
            "Type": 'ClaimBilling'
            // "appointmentinfo": appointmentinfo,
        };

        $scope.modaldepositInstance = $uibModal.open({
            "templateUrl": "templates/consultation/payor/AddupdatePatientDeposits.html",
            "controller": "EhnoteAddupdatePatientDepositsCtrl",
            "resolve": {
                "Selectobj": function () { return obj; },
            },
            "size": "lg", //"md",
            "backdrop": "static",
            "keyboard": false,
            "windowClass": "inventory-full-popup"
        });

        $scope.modaldepositInstance.result.then(function (resp) {
            $scope.getPatientPayment($scope.patientid);
        }, function (cancel) {

        });

    }

