    $scope.GetFilteredVisionDetails = function (type) {
        //$scope.PastVisitsNavObj.pastvsttab = type || 2;
        let params = {
            "PatientId": $scope.cacheStorageItem.PatientID || 0,
            /*"UserId": $scope.UserId || 0,*/
            "FromDate": $filter('date')(new Date($scope.GetvisionPastVisitsDatesObj.FromDate), "yyyy-MM-dd"),
            "Todate": $filter('date')(new Date($scope.GetvisionPastVisitsDatesObj.ToDate), "yyyy-MM-dd"),
            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
            "DefaultAll": $scope.GetvisionPastVisitsDatesObj.DefaultAll || false
        };
        eHnoteSettingsDataService.GetFilteredVisionDetails(params).then(function (response) {
            $scope.FilteredVisionDetails = [];
            if (response.data.status === "Success") {
                var responsecopy = angular.copy(response.data);
                var uniqApptsList = _.uniq(responsecopy.VisionDetails, function (x) {
                    return x.AppointmentId;
                });
                var Appts = [];
                angular.forEach(uniqApptsList, function (item) {
                    Appts.push(item.AppointmentId);
                });
                $scope.GetPVVisionObj = function () {
                    return {
                        "AppointmentId": 0,
                        "ApptDate": "",
                        "UnAidedDistanceR": "",
                        "UnAidedNearR": "",
                        "UnAidedDistanceL": "",
                        "UnAidedNearL": "",
                        "AidedDistanceR": "",
                        "AidedNearR": "",
                        "AidedDistanceL": "",
                        "AidedNearL": "",
                        "AidedCLDistanceR": "",
                        "AidedCLNearR": "",
                        "AidedCLDistanceL": "",
                        "AidedCLNearL": "",
                        "TACRemarksR": "",
                        "TACRemarksL": "",
                        "PinHoleRemarksR": "",
                        "PinHoleRemarksL": ""
                    };
                };

                angular.forEach(Appts, function (kitem) {
                    let tempArray = $filter('filter')(response.data.VisionDetails, { "AppointmentId": kitem }, true);
                    let VisionObj = $scope.GetPVVisionObj();
                    VisionObj.AppointmentId = kitem;
                    VisionObj.ApptDate = tempArray[0].AppointmentDate;
                    angular.forEach(tempArray, function (item) {
                        if (kitem == item.AppointmentId && item.InvestigationId == 4) {
                            VisionObj.UnAidedDistanceR = item.RightEyeValues.Distance;
                            VisionObj.UnAidedNearR = item.RightEyeValues.Near;
                            VisionObj.UnAidedDistanceL = item.LeftEyeValues.Distance;
                            VisionObj.UnAidedNearL = item.LeftEyeValues.Near;
                        }
                        if (kitem == item.AppointmentId && item.InvestigationId == 5) {
                            VisionObj.AidedDistanceR = item.RightEyeValues.Distance;
                            VisionObj.AidedNearR = item.RightEyeValues.Near;
                            VisionObj.AidedDistanceL = item.LeftEyeValues.Distance;
                            VisionObj.AidedNearL = item.LeftEyeValues.Near;
                        }
                        if (kitem == item.AppointmentId && item.InvestigationId == 2071) {
                            VisionObj.AidedCLDistanceR = item.RightEyeValues.Distance;
                            VisionObj.AidedCLNearR = item.RightEyeValues.Near;
                            VisionObj.AidedCLDistanceL = item.LeftEyeValues.Distance;
                            VisionObj.AidedCLNearL = item.LeftEyeValues.Near;
                        }
                        if (kitem == item.AppointmentId && item.InvestigationId == 2076) {
                            VisionObj.TACRemarksR = item.RightEyeValues.Remarks;
                            VisionObj.TACRemarksL = item.LeftEyeValues.Remarks;
                        }
                        if (kitem == item.AppointmentId && item.InvestigationId == 13) {
                            VisionObj.PinHoleRemarksR = item.RightEyeValues.Remarks;
                            VisionObj.PinHoleRemarksL = item.LeftEyeValues.Remarks;
                        }
                    });
                    $scope.FilteredVisionDetails.push(VisionObj);
                });
                //console.log($scope.FilteredVisionDetails);
                $scope.PastVisitsNavObj.pastvsttab = type || 2;

            }

        }, function (data) {
            console.log(data);
            alertify.error("Fetching data failed!");
        });
    };

