    $scope.getFavClassIcon = function (item) {

        var defaultclass = 'bg-efefef';

        if (item.DiagnosisStatus == 58) {
            defaultclass = 'bg-acute';
        } else if (item.DiagnosisStatus == 59) {
            defaultclass = 'bg-lowpriority';
        } else if (item.DiagnosisStatus == 60) {
            defaultclass = 'bg-High-Priority';
        } else if (item.DiagnosisStatus == 61) {
            defaultclass = 'bg-chronic';
        }

        return defaultclass;
    };

