    $scope.PCPGetDataClick = function (item) {

        if (item == true) {
            $scope.PatientDesignatedInfo.PCPCheckBox = true;
            $scope.PatientDesignatedInfo.PCPobj = "";

        } else {
            $scope.PatientDesignatedInfo.PCPobj = "";
            $scope.PatientDesignatedInfo.PCP = "";
            $scope.PatientDesignatedInfo.PCPDoctorName = "";
            $scope.PatientDesignatedInfo.PcpNPI = "";
            $scope.PatientDesignatedInfo.PCPEmailId = "";
            $scope.PatientDesignatedInfo.PCPContactNo = "";
            $scope.PatientDesignatedInfo.PCPReferenceNumber = "";
            $scope.PatientDesignatedInfo.PCPReferralDate = null;
            $scope.PatientDesignatedInfo.PCPNotes = "";
            $scope.PatientDesignatedInfo.IsPCPCoManagerInd = false;
            if ($scope.PatientDesignatedInfo.PatientPCPDocuments.length > 0) {

                if ($scope.PatientDesignatedInfo.ReferalCheckBox == false && $scope.PatientDesignatedInfo.PCPCheckBox == false) {


                    var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to delete Upload Documents? </h4>", function () {


                        if ($scope.PatientDesignatedInfo.PatientPCPDocuments.length > 0) {
                            angular.forEach($scope.PatientDesignatedInfo.PatientPCPDocuments, function (PcpdocumentId) {


                                $scope.DocumentPcp =
                                {
                                    "UserId": $scope.UserId,
                                    "HospitalID": $scope.HospitalId,
                                    "PatientDesignatedDocumentDetail": [{
                                        "DocumentId": PcpdocumentId.PatientPCPDocumentId,
                                        "DocumentTypeId": 4,
                                        "DocumentName": PcpdocumentId.DocumentName,
                                        "DocumentExt": PcpdocumentId.DocumentExt,
                                        "S3URL": PcpdocumentId.S3URL,
                                        "DeleteInd": "Y"
                                    }]
                                }
                                eHnotePatientDataService.DeleteDesignatedDocumentDetailsById($scope.DocumentPcp).then(function (resp) {
                                    console.log(resp);
                                    if (resp.data.status == "Success") {

                                        var filterTinsDesignatedInfo = $filter("filter")($scope.PatientDesignatedInfo.PatientPCPDocuments, { "PatientPCPDocumentId": PcpdocumentId.PatientPCPDocumentId }, true) || [];
                                        if (filterTinsDesignatedInfo.length > 0) {
                                            var indexDesignated = $scope.PatientDesignatedInfo.PatientPCPDocuments.indexOf(filterTinsDesignatedInfo[0]);
                                            $scope.PatientDesignatedInfo.PatientPCPDocuments.splice(indexDesignated, 1);
                                        }

                                        var filterTinsSummary = $filter("filter")($scope.PatientDesignatedSummary.SummaryPcpDocument, { "PatientPCPDocumentId": PcpdocumentId.PatientPCPDocumentId }, true) || [];
                                        if (filterTinsSummary.length > 0) {
                                            var indexSummary = $scope.PatientDesignatedSummary.SummaryPcpDocument.indexOf(filterTinsSummary[0]);
                                            $scope.PatientDesignatedSummary.SummaryPcpDocument.splice(indexSummary, 1);
                                        }
                                        var filterTins = $filter("filter")($scope.PatientDesignatedSummary.PatientPCPDocuments, { "PatientPCPDocumentId": PcpdocumentId.PatientPCPDocumentId }, true) || [];
                                        if (filterTins.length > 0) {
                                            var indexVlaue = $scope.PatientDesignatedSummary.PatientPCPDocuments.indexOf(filterTins[0]);
                                            $scope.PatientDesignatedSummary.PatientPCPDocuments.splice(indexVlaue, 1);

                                        }



                                    }

                                    alertify.success("Deleted Successfully");
                                }, function (err) {
                                    console.log(err);
                                    alertify.error("Deleting Failed");
                                });

                            })


                        }
                    })
                }

            }
            $scope.PatientDesignatedInfo.PCPCheckBox = false;
        }
    }

