    $scope.getApptAdditionalDetails1 = function (id, type) {
        id = id || null;
        eHnoteMainAppointmentService.getAdditionalApptDetailsById(id).then(function (resp) {

            resp.data = resp.data || [];


            $scope.AppointmentTypeId =resp.data[0].Patient.AppointmentTypeId || 0 ;
            $scope.cacheStorageItem.AppointmentId = resp.data[0].Patient.AppointmentId || 0 ;

            $scope.mainobj.Patientlist = resp.data[0].Patient || [];
            $scope.mainobj.AppointmentInsuranceList = resp.data[0].AppointmentInsuranceList || [];
            $scope.PreAuthObj = $scope.PreAuthObj || {};
            if ($scope.PreAuthObj != undefined) {
                resp.data[0].AppointmentPreAuthDetails = resp.data[0].AppointmentPreAuthDetails||[];
                if (resp.data[0].AppointmentPreAuthDetails.length > 0) {
                    let AppointmentPreauthDetails = resp.data[0].AppointmentPreAuthDetails||[];
                    $scope.PreAuthObj.PreAuthDetails = AppointmentPreauthDetails || [];
                    $scope.PreAuthNotesList = [];
                    if (AppointmentPreauthDetails.length > 0) {
                        $scope.PreAuthNotesList = AppointmentPreauthDetails[0].PreAuthNotesList || [];
                    }
                } else {
                    $scope.PreAuthObj.PreAuthDetails=[];
                    $scope.PreAuthNotesList = [];
                }
            }

            if (resp.data.length > 0) {

                $scope.parentProfileTab.AppointmentAdditionalDetails = resp.data[0];
                $scope.AppointmentNotesArray = resp.data[0].AppointmentNotes;
                $scope.SelectedAppointmentObj.PaymentTypeId = resp.data[0].PaymentTypeId;
                //if (resp.data[0].AppointmentDetails.length > 0 ) {
                //    $scope.selectedAppointmentObject.OtherNotesCreatedBy = resp.data[0].AppointmentDetails[0].ModifiedBy || "";
                //    $scope.selectedAppointmentObject.OtherNotesCreatedDt = resp.data[0].AppointmentDetails[0].ModifiedDt || "";
                //}

                console.log(resp.data);




                if (resp.data[0].AppointmentDetails.length > 0) {
                    var obj = resp.data[0].AppointmentDetails[0];

                    var tmpd1 = $filter('date')(obj.AppointmentDate, "yyyy-MM-dd");
                    var tmpd2 = $filter('date')(new Date(), "yyyy-MM-dd");

                    let isPastDate = false;
                    if (tmpd2 > tmpd1) {
                        isPastDate = true;
                    }
                    obj.NoShowReasonId = obj.NoShowReasonId || null;
                    if (isPastDate && obj.IsNoShowAppointment) {
                        $scope.SelectedAppointmentObj.IsNoShowIconInd = true;
                    } else {
                        $scope.SelectedAppointmentObj.IsNoShowIconInd = false;
                    }

                    if (obj.RescheduledAppointmentId !== 0) {
                        $scope.SelectedAppointmentObj.RescheduledAppointmentId = obj.RescheduledAppointmentId;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentDate = obj.RescheduledAppointmentDate;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = obj.RescheduledAppointmentStartTime;
                        $scope.SelectedAppointmentObj.RescheduledAppointmentEndTime = obj.RescheduledAppointmentEndTime;
                        $scope.SelectedAppointmentObj.RescheduledDoctorId = obj.RescheduledDoctorId;






                        var starray = $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime.split(":");
                        var st1 = starray[0];
                        var st2 = starray[1];

                        console.log(st1, st2);

                        var stime = getdtTimes(st1, st2);

                        $scope.SelectedAppointmentObj.RescheduledAppointmentStartTime = stime;
                    }


                    $scope.SelectedAppointmentObj.InformantId = obj.InformantId || null;
                    $scope.othernotes.Notes = obj.OtherNotes || "";
                    $scope.othernotes.CreatedDt = obj.ModifiedDt || "";
                    $scope.othernotes.CreatedBy = obj.ModifiedBy || "";


                    var PatientInsuranceplanList = resp.data[0].PatientInsuranceList || [];

                    if (type == 'ShowInsPlanRemarks' && $scope.parentProfileTab.PatientAndApptTab == 2 && $scope.PreviousUrl === '/op') {
                        if (PatientInsuranceplanList.length > 0) {

                            var TempPatientInsuranceList = [];
                            var TempPatientInsuranceList = $filter("filter")(PatientInsuranceplanList, function (item) {
                                return item.Remarks !== '' && item.IdentifierId == 1;
                            });

                            if (TempPatientInsuranceList.length > 0) {
                                if ($scope.RoleId == 2 || $scope.RoleId == 71) {
                                    $scope.showInsurancePlanAlert(TempPatientInsuranceList[0]);
                                } else if ($scope.UserAccessRights.AllAccessRights.ShowPayorPlanRemarks) {
                                    $scope.showInsurancePlanAlert(TempPatientInsuranceList[0]);
                                }
                            }

                        }
                    }

                    if (PatientInsuranceplanList.length > 0) {
                        let primaryinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 1 }, true) || [];
                        $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = (primaryinsurance.length > 0) ? true : false;
                        let secondaryinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 2 }, true) || [];
                        $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt = (secondaryinsurance.length > 0) ? true : false;
                        let otherinsurance = $filter('filter')(PatientInsuranceplanList, { 'IsConnectToFutureAppointment': true, 'IdentifierId': 5 }, true) || [];
                        $scope.FutureApptInsuranceObj.IsOtherInsuranceAddToFutureAppt = (otherinsurance.length > 0) ? true : false;
                    }
                    $scope.SelectedAppointmentObj.PreAdmSurgeryList = [];
                    $scope.SelectedAppointmentObj.SurgeryList = [];

                    $scope.SelectedAppointmentObj.AppointmentTypeId = obj.AppointmentTypeId || null;
                    if (obj.AppointmentTypeId == 7) {
                        $scope.SelectedAppointmentObj.PreAdmSurgeryList = obj.PreAdmSurgeryList || [];
                    } else if (obj.AppointmentTypeId == 4 || obj.AppointmentTypeId == 14) {
                        $scope.SelectedAppointmentObj.SurgeryList = obj.SurgeryList || [];
                    }
                    $scope.SelectedAppointmentObj.OtherProviderDoctorID = resp.data[0].AppointmentDetails[0].OtherProviderDoctorID || 0;
                    $scope.SelectedAppointmentObj.SurgeryReferralDoctorId = resp.data[0].AppointmentDetails[0].SurgeryReferralDoctorId || 0;
                    $scope.SelectedAppointmentObj.ReasonTypeId = resp.data[0].AppointmentDetails[0].ReasonTypeId || 0;
                }

            } else {
                $scope.AppointmentNotesArray = [];
            }
            $scope.AddToCache();
        }, function (err) {
            console.log(err);
            alertify.error("Getting data failed");
        });
    };

