    $scope.AddInsurenceToFutureAppointment = function (obj, checked, type) {
        obj.StatusId = obj.StatusId || 0;
        if (obj.StatusId == 2 || obj.StatusId == 3 || obj.StatusId == 4 || obj.StatusId == 5) {
            $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = false;
            alertify.error('The Insurance is not in Active Status you cant connect to future');
            return false;
        }
        if (type == 2) {
            if ($scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt == false) {
                $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt = false;
                alertify.error('Dont have access to connect this insurence to future! Please Add Primary Insurance');
                return false;
            }
        }
        if (type == 3) {
            if ($scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt == false || $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt == false) {
                $scope.FutureApptInsuranceObj.IsOtherInsuranceAddToFutureAppt = false;
                alertify.error('Dont have access to connect this insurence to future! Please Add Primary Insurance');
                return false;
            }
        }
        if ($scope.SelectedAppointmentObj.PatientInsuranceList.length > 0) {
            var count = 0;
            angular.forEach($scope.SelectedAppointmentObj.PatientInsuranceList, function (siten) {
                if (siten.StatusId != 1) {
                    if (siten.StatusId != 1 && siten.IdentifierId == 2) {
                        alertify.error('The Secounday Insurance is not in Active Status you cant connect to future');
                        count++;
                    }
                    if (siten.StatusId != 1 && siten.IdentifierId == 5) {
                        alertify.error('The Other Insurance is not in Active Status you cant connect to future');
                        count++;
                    }
                }
            });
            if (count > 0) {
                $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = false;
                return false;
            }
        }
        if (checked) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to Add future Appointment? </h4>", function () {
                $scope.FutureApptInsuranceObj.IsInsuranceAddToFutureAppt = checked;
                var ConnectInsurencefutureApptObj = {
                    //   "AppointmentId": $scope.cacheStorageItem.appointmentid || 0,
                    "AppointmentId": $scope.appointmentid || 0,
                    "PatientId": $scope.cacheStorageItem.patientid || 0,
                    "PayorId": obj.PayorId || "",
                    "PlanId": obj.PlanId || "",
                    "PatientInsuranceDetailId": obj.PatientInsuranceDetailId || "",
                    "IdentifierId": obj.IdentifierId || "",
                    "OrganizationPayorId": obj.OrganizationPayorId || "",
                    "IsInsuranceAddToFutureAppt": $scope.FutureApptInsuranceObj.IsInsuranceAddToFutureAppt || false,
                    "UserId": $scope.UserId || 0,
                    "HospitalId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID || 0,
                }
                eHnoteMainAppointmentService.AddUpdateInsuranceConnectToFuture(ConnectInsurencefutureApptObj).then(function (resp) {
                    if (resp.data.Status == "Success") {
                        alertify.success("Patient  insurance is added to future appointment ");
                        if (type == 1) {
                            $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = true;
                        }
                        if (type == 2) {
                            $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt = true;
                        }
                        if (type == 3) {
                            $scope.FutureApptInsuranceObj.IsOtherInsuranceAddToFutureAppt = true;
                        }
                        $scope.FutureApptInsuranceObj.IsInsuranceAddToFutureAppt = false;
                        $scope.GetUpcomingAppointments($scope.cacheStorageItem.patientid);
                    }
                }, function (err) {
                    alertify.error("Getting Failed");
                });
            },
                function () {

                    if (type == 1) {
                        $scope.FutureApptInsuranceObj.IsPrimaryInsuranceAddToFutureAppt = false;
                    }
                    if (type == 2) {
                        $scope.FutureApptInsuranceObj.IsSecondaryInsuranceAddToFutureAppt = false;
                    }
                    if (type == 3) {
                        $scope.FutureApptInsuranceObj.IsOtherInsuranceAddToFutureAppt = false;
                    }
                    r = "You pressed Cancel!";
                });
        }
    }


