        var checkedArray = _.where($scope.LogMaintainAllUsersList, { isChecked: true });
        $scope.PatientLevelLogsObj.AllUsersCheck = checkedArray.length > 0 && $scope.LogMaintainAllUsersList.length === checkedArray.length ? true : false;

