    $scope.GetPatientAllAppointmentDataExportInfo = function () {
        $scope.Arr_exportedData = [];
        $scope.dataobj = {
            "HospitalId": $scope.HospitalId,
            "PatinetId": $scope.cacheStorageItem.PatientID
        }
        eHnotePatientDataService.GetPatientAllAppointmentDataExportInfo($scope.dataobj).then(function (response) {
            console.log(response);
            if (response.data != null || response.data != undefined) {
                if (response.data.Status === "Success") {
                    if (response.data.Attachments.length > 0) {
                        $scope.copyarry = response.data.Attachments;
                        for (i = 0; i < response.data.Attachments.length; i++) {

                            $scope.Arr_exportedData.push({
                                "PatientId": $scope.copyarry[i].PatientId,
                                "AppointmentId": $scope.copyarry[i].AppointmentId,
                                "AppointmentDoctorName": $scope.copyarry[i].AppointmentDoctorName,
                                "AppointmentDate": $scope.copyarry[i].AppointmentDate,
                                "PatientDataExportId": $scope.copyarry[i].PatientDataExportId,
                                "FolderPath": $scope.copyarry[i].FolderPath,
                                "ExportedBy": $scope.copyarry[i].ExportedBy,
                                "ExportedDate": $scope.copyarry[i].ExportedDate,
                                "DeleteInd": $scope.copyarry[i].DeleteInd,
                                "CreatedUserName": $scope.copyarry[i].CreatedUserName,
                                "ischeckflag": $scope.checkflag,
                                "IsExported": $scope.copyarry[i].IsExported,
                                "Files": $scope.copyarry[i].Files
                            })
                        }
                        console.log($scope.Arr_exportedData)
                    }
                } else {
                    alertify.error(response);
                }
            }
        },
            function (error) {
                console.log(error);
                alertify.error(error);
            });
    };




