    $scope.handleCheckboxClick = function (i, exportdataobj) {
        $scope.new_data = [];
        if ($scope.Arr_exportedData[i].Files.length == 0) {
            alertify.error("The Appointment Dont have any file Uploads");
            exportdataobj.checkflag = false;
            return false;
        }
        console.log($scope.Arr_exportedData)
        $scope.Arr_exportedData[i].ischeckflag = true
        if ($scope.Arr_exportedData[i].ischeckflag == true && $scope.Arr_exportedData[i].IsExported == false) {
            $scope.new_data.push({
                "PatientId": $scope.Arr_exportedData[i].PatientId,
                "AppointmentId": $scope.Arr_exportedData[i].AppointmentId,
                "AppointmentDoctorName": $scope.Arr_exportedData[i].AppointmentDoctorName,
                "AppointmentDate": $scope.Arr_exportedData[i].AppointmentDate,
                "PatientDataExportId": $scope.Arr_exportedData[i].PatientDataExportId,
                "FolderPath": $scope.Arr_exportedData[i].FolderPath,
                "ExportedBy": $scope.Arr_exportedData[i].ExportedBy,
                "ExportedDate": $scope.Arr_exportedData[i].ExportedDate,
                "DeleteInd": $scope.Arr_exportedData[i].DeleteInd,
                "CreatedUserName": $scope.Arr_exportedData[i].CreatedUserName,
                "Files": $scope.Arr_exportedData[i].Files,
                "ischeckflag": $scope.checkflag
            })
        } else if ($scope.new_data[i] != undefined) {
            $scope.new_data.splice(i, 1)[0];
        } else {
            // alertify.error("No data available");
        }
    }


    $scope.SpecialCharacterAlert = function (Type, firstName) {
        var specialcharaters = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.`~<>\/?]/;
        if (specialcharaters.test(firstName)) {
            if (Type == 1) {
                $scope.PatientDetailsInfo.FirstName = $scope.PatientDetailsInfo.FirstName.replace(/[^\w\s]/gi, '');
                $scope.PatientDetailsInfo.FirstName = $scope.PatientDetailsInfo.FirstName.replace(/_/g, '');

                $scope.FamilyInfo.FamilyArray = $scope.FamilyInfo.FamilyArray || [];
                if ($scope.FamilyInfo.FamilyArray.length > 0) {
                    angular.forEach($scope.FamilyInfo.FamilyArray, function (fitem) {
                        fitem.FirstName = fitem.FirstName.replace(/[^\w\s]/gi, '');
                        fitem.FirstName = fitem.FirstName.replace(/_/g, '');
                    });
                }
            }
            else if (Type == 2) {
                $scope.PatientDetailsInfo.MiddleName = $scope.PatientDetailsInfo.MiddleName.replace(/[^\w\s]/gi, '');
                $scope.PatientDetailsInfo.MiddleName = $scope.PatientDetailsInfo.MiddleName.replace(/_/g, '');

                $scope.FamilyInfo.FamilyArray = $scope.FamilyInfo.FamilyArray || [];
                if ($scope.FamilyInfo.FamilyArray.length > 0) {
                    angular.forEach($scope.FamilyInfo.FamilyArray, function (fitem) {
                        fitem.LastName = fitem.LastName.replace(/[^\w\s]/gi, '');
                        fitem.LastName = fitem.LastName.replace(/_/g, '');
                    });
                }
            }
            else if (Type == 3) {
                $scope.PatientDetailsInfo.LastName = $scope.PatientDetailsInfo.LastName.replace(/[^\w\s]/gi, '');
                $scope.PatientDetailsInfo.LastName = $scope.PatientDetailsInfo.LastName.replace(/_/g, '');
            }
            else if (Type == 4) {
                $scope.PatientDetailsInfo.SecondLastName = $scope.PatientDetailsInfo.SecondLastName.replace(/[^\w\s]/gi, '');
                $scope.PatientDetailsInfo.SecondLastName = $scope.PatientDetailsInfo.SecondLastName.replace(/_/g, '');
            } else {
                $scope.PatientDetailsInfo.PreviousName = $scope.PatientDetailsInfo.PreviousName.replace(/[^\w\s]/gi, '');
                $scope.PatientDetailsInfo.PreviousName = $scope.PatientDetailsInfo.PreviousName.replace(/_/g, '');
            }
            alertify.error("Special Characters are not allowed. Please check");
            return false;
        }
    }

    $scope.downloadFile = function (s3Url, filename) {
        // Create a hidden form element
        var form = document.createElement('form');
        form.style.display = 'none';
        document.body.appendChild(form);

        // Create an input field for the file URL
        var inputUrl = document.createElement('input');
        inputUrl.type = 'text';
        inputUrl.name = 'url';
        inputUrl.value = s3Url;
        form.appendChild(inputUrl);

        // Create an input field for the file name
        var inputFilename = document.createElement('input');
        inputFilename.type = 'text';
        inputFilename.name = 'filename';
        inputFilename.value = filename;
        form.appendChild(inputFilename);

        // Set the form's action to a download endpoint on your server
        form.action = '/download-endpoint'; // Replace with your actual server endpoint

        // Set the form's method to POST
        form.method = 'POST';

        // Submit the form to trigger the download
        form.submit();

        // Clean up the form element
        form.remove();
    };

