    $scope.GetFilteredPlanHxDetails = function (type) {

        let params = {
            "PatientId": $scope.cacheStorageItem.PatientID || 0,
            "FromDate": $filter('date')(new Date($scope.GetIOPPastVisitsDatesObj.FromDate), "yyyy-MM-dd"),
            "Todate": $filter('date')(new Date($scope.GetIOPPastVisitsDatesObj.ToDate), "yyyy-MM-dd"),
            "OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
            "DefaultAll": $scope.GetIOPPastVisitsDatesObj.DefaultAll || false
        };
        eHnoteSettingsDataService.GetFilteredPlanHxDetails(params).then(function (response) {

            $scope.FilteredPlanHxDetails = [];
            $scope.PlanHxDetailsEmpty = false;
            if (response.data.status === "Success") {
                $scope.FilteredPlanHxDetails = response.data.rows || [];
                $scope.PastVisitsNavObj.pastvsttab = type || 8;
            }

            var i = 0;
            if ($scope.FilteredPlanHxDetails.length > 0) {
                angular.forEach($scope.FilteredPlanHxDetails, function (item) {
                    item.AssessmentPlan = $filter("filter")(item.AssessmentPlan, function (iterator, ind) { return iterator.PlanofDiscussionsNotes != '' && iterator.DoctorNotes != '' && iterator.PatientInstructions != '' && iterator.ActionsTaken != ''; }) || [];

                    if (item.AssessmentPlan.length !== 0 || item.InvestigationsDetails.length !== 0 || item.ProceduresDetails.length !== 0 || item.SurgeriesDetails.length !== 0) {
                        i++;
                    }
                });

            }

            if (i == 0) {
                $scope.PlanHxDetailsEmpty = true;
            }

        }, function (err) {
            alertify.error("Fetching Data Failed!");
        });
    };

