    $scope.editPatientInfoPopup = function () {
        var Patobj = {
            "Appointmentid": $scope.cacheStorageItem.appointmentid || 0,
            "patientid": $scope.patientid || 0,
            "PatientDisplayID": $scope.PatientDisplayID || 0,
            "UserId": $scope.UserId || 0,
            "Allcountries": $scope.Allcountries || [],
            "PatientEthnicityList": $scope.PatientEthnicityList || [],
            "PatientRaceList": $scope.PatientRaceList,
            "PatientLanguageList": $scope.PatientLanguageList || [],
            "PatientLanguageExpressionList": $scope.PatientLanguageExpressionList || [],
            "PatientLanguageProficiencyList": $scope.PatientLanguageProficiencyList || [],
            "PatientSexualOrientationList": $scope.PatientSexualOrientationList || [],
            "PatientGenderIdentityList": $scope.PatientGenderIdentityList || [],
            "InsuranceStatusList": $scope.InsuranceStatusList || [],
            "TitlesList": $scope.TitlesList || [],
            "IsCoomingFrom": 'PatientProfile'
        }
        $scope.EditPopoverInstance = $uibModal.open({
            "templateUrl": "templates/uibpopups/editPatientInfoPopup.html",
            "backdrop": "static",
            "keyboard": false,
            /*"scope": $scope,*/
            "windowClass": "offcanves-right",
            "controller": "EditPatientInfoPopupCtrl",
            "resolve": {
                "Headers": function () { return $scope.Headers; },
                "PatientDetailsInfo": function () { return angular.copy($scope.PatientDetailsInfo); },
                "PatientInsuranceObj": function () { return angular.copy($scope.PatientInsuranceObj); },
                "SaveTypeObj": function () { return angular.copy($scope.SaveTypeObj); },
                "Patobj": function () { return angular.copy(Patobj); },
                "DemographicInfo": function () { return angular.copy($scope.DemographicInfo); },
                "FamilyInfo": function () { return angular.copy($scope.FamilyInfo); },
                "PatientAddressInfo": function () { return angular.copy($scope.PatientAddressInfo); },
                "LogObj": function () { return angular.copy($scope.LogObj); },
            },
        });
        $scope.EditPopoverInstance.result.then(function (tab) {
            $scope.SelectPatient($scope.patientid);
            if ($scope.PatientInsuranceObj.IsAddnewInsuranceInd == true) {
                $scope.SelectPatient($scope.patientid);
            }
            if (tab === 6) {
                $scope.PatientInsuranceInfo = GetInsuranceInfo();
                $scope.PatientInsuranceObj = GetInsuranceObj();
                if ($scope.PatientInsuranceObj.IsInsuranceConnectedAppointment) {
                    $scope.PatientInsuranceObj.IsAddnewInsurancePlanInd = false;
                    $scope.PatientInsuranceObj.IsAddnewInsuranceInd = false;
                }
            }
            $scope.EditPopoverInstance.dismiss("cancel");
        }, function (cancel) {

        });
    };
