    $scope.PreAuthNotesList=[];
    $scope.GetPatientAscPreAuthDetails = function (item) {
        $scope.mainobj = $scope.mainobj || {};
        let AppointmentId = $scope.mainobj.AppointmentId || 0;
        let PatientId = $scope.mainobj.PatientId || 0;
        let Obj = {
            "PatientId": PatientId,
            "AppointmentId": AppointmentId,
        }
        eHnotePatientDataService.GetPatientAscPreAuthDetails(Obj).then(function (resp) {
            let AppointmentPreauthDetails = [], PatientInsuranceList = [];
            let PreAuthNotesList = [], PatientDetails = [], PreAuthLogs = [];
            if (resp.data.rows.length > 0) {
                AppointmentPreauthDetails = resp.data.rows || [];
                
            }
            if (AppointmentPreauthDetails.length > 0) {
                $scope.PreAuthObj.PreAuthDetails = AppointmentPreauthDetails || [];
                //AppointmentPreauthDetails[0].PreAuthNotesList = AppointmentPreauthDetails[0].PreAuthNotesList || [];
                angular.forEach($scope.PreAuthObj.PreAuthDetails, function (aaitem) {
                    aaitem.StartDate = aaitem.StartDate || null;
                    aaitem.EndDate = aaitem.EndDate || null;
                    if (aaitem.StartDate != null) {
                        aaitem.StartDate = $filter('date')(aaitem.StartDate, "MM-dd-yyyy");
                    }
                    if (aaitem.EndDate != null) {
                        aaitem.EndDate = $filter('date')(aaitem.EndDate, "MM-dd-yyyy");
                    }
                });
            } else {
                $scope.PreAuthObj.PreAuthDetails=[];
                $scope.PreAuthNotesList=[];
            }
            $scope.PreAuthNotesList = resp.data.PreAuthNotesList || [];

        });
    }

    $scope.PreAuthinfoPopup = function () {
        let Obj = {
            "PatientId": $scope.cacheStorageItem.PatientID,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId,
        }
        eHnotePatientDataService.GetPatientPreOpCallDetailsList(Obj).then(function (resp) {
            if (resp.data.status == "Success") {              
                if (resp.data.AppointmentList.length > 0) {
                    $scope.preAuthObj = resp.data.AppointmentList[0].PreAuthDetails || [];            
                    if ($scope.preAuthObj.StartDate  !="" ) {
                        $scope.preAuthObj.StartDate = new Date($scope.preAuthObj.StartDate.replace(" ", "T")) || "";
                    }
                    if ($scope.preAuthObj.EndDate != "") {
                        $scope.preAuthObj.EndDate = new Date($scope.preAuthObj.EndDate.replace(" ", "T")) || "";
                    }
                }            
            }
        }, function (err) {

        });
    };
