    $scope.navtoOpenAddDepositAmount = function () {
        var params = {
            "OrganizationId": $scope.HospitalId,
            "FacilityName": ""
        }
        var ApptInsuranceObj = {
            "AppointmentId": $scope.cacheStorageItem.appointmentid,
            "PatientId": $scope.cacheStorageItem.PatientID,
            "SendPlanDetailsInd": 1
        }
        let Patientobj={}
        $q.all([
            eHnoteMainAdminServices.GetOrganizationFacilityDetails(params),
            eHnoteInsuranceService.GetAppointmentInsuranceDetailsListByStatus(ApptInsuranceObj),
        ]).then(function (resp) {
            if (resp[0].data.status === "Success") {
                resp[0].data.rows = resp[0].data.rows || [];
                if (resp[0].data.rows.length > 0) {
                    $scope.OrganizationFacilityList = angular.copy(resp[0].data.rows);
                }
                
            }

            if (resp[1].data.Patient != ''){
               
                Patientobj.PatientId = resp[1].data.Patient.PatientId || null;
               Patientobj.FirstName = resp[1].data.Patient.FirstName || '';
                Patientobj.LastName = resp[1].data.Patient.LastName || '';
                Patientobj.FullName = resp[1].data.Patient.FullName || '';
                Patientobj.Sex = resp[1].data.Patient.Sex || '';
                Patientobj.PatientSSN = resp[1].data.Patient.PatientSSN || '';
                let MobileNo = resp[1].data.Patient.MobileNo || '';
                Patientobj.EmailId = resp[1].data.Patient.EmailId || '';
                Patientobj.PatientDisplayId = resp[1].data.Patient.PatientDisplayId || '';
                if (resp[1].data.Patient.DOB != "") {
                    Patientobj.DOB = $filter('date')(resp[1].data.Patient.DOB, "MM-dd-yyyy");
                    }
                    if (MobileNo != '') {
                        var obj = eHnoteUserDataService.UsMobileFormatChange(MobileNo);
                       Patientobj.MobileNo = obj.UsFormatMobileNumber;
                    }

                

            }


            $scope.obj = {
                "PatientId": $scope.cacheStorageItem.PatientID,
                "Type": '',
                "UsersList": $scope.allUserList,
                "Patientobj": Patientobj,
                "ClaimDetailsList": $scope.ClaimDetailsList,
                "OrganizationFacilityList": $scope.OrganizationFacilityList,
                "DepositTypes": $scope.DepositTypes,
                "WriteOffReasons": $scope.WriteOffReasons,
                "BillingProviderName": $scope.BillingProviderName || "",
                "FacilityName": $scope.FacilityName || ""
            }

            var modalInstance = $uibModal.open({
                "templateUrl": "templates/UsClaims/AddPatientDepositPopup.html",
                "controller": "UsAddPatientDepositsCtrl",
                "resolve": {
                    "Selectobj": function () { return $scope.obj; },
                },
                "size": "lg",
                "backdrop": "static",
                "keyboard": false,
                "windowClass": "modal__ninety--"

            });

            modalInstance.result.then(function () {

                $scope.getPatientDepositAmountById();

            }, function () { });
        });
      
    }

